#pragma once
#include <stdint.h>

typedef struct { int32_t identifier; float x; float y; } TFContact;
typedef void (*TFFrameHandler)(uint64_t device, const TFContact *contacts, int count, double timestamp);
// Returns device count, -1 if the framework is unavailable, -2 for missing symbols.
int TFStart(TFFrameHandler handler);
int TFRefresh(void);
void TFStop(void);
// Fresh hardware position for filtering the native click generated by tap-to-click.
int TFRecentSingleContact(TFContact *contact);
